package com.mygo.music;

import android.app.*;
import android.content.*;
import android.media.*;
import android.net.Uri;
import android.os.SystemClock;
import org.json.*;
import java.io.*;
import java.net.*;
import java.util.*;
import java.util.concurrent.*;

/** Real Android executable, native audio clock and offline files, never a mocked decoder. */
final class NativeAudioChecks {
    final Instrumentation test;final Context context;final CompletionChecks helpers;
    NativeAudioChecks(Instrumentation test){this.test=test;context=test.getTargetContext();helpers=new CompletionChecks(test);}
    static void check(boolean ok,String message){if(!ok)throw new AssertionError(message);}
    byte[] asset(String name)throws Exception{try(InputStream in=test.getContext().getAssets().open("port-fixtures/"+name);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] bytes=new byte[8192];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);return out.toByteArray();}}
    final class Server implements AutoCloseable {
        final ServerSocket socket=new ServerSocket(0,12,InetAddress.getByName("127.0.0.1"));final ExecutorService workers=Executors.newCachedThreadPool();
        final CountDownLatch held=new CountDownLatch(1),release=new CountDownLatch(1);volatile boolean closed,badHeader;volatile int segments,keys;String cross="";final boolean auth;
        Server(boolean auth)throws Exception{this.auth=auth;Thread thread=new Thread(()->{while(!closed)try{Socket client=socket.accept();workers.execute(()->serve(client));}catch(Exception ignored){}});thread.setDaemon(true);thread.start();}
        String base(){return "http://127.0.0.1:"+socket.getLocalPort();}
        void serve(Socket client){try(Socket current=client){current.setSoTimeout(10000);BufferedReader input=new BufferedReader(new InputStreamReader(current.getInputStream(),"US-ASCII"));String first=input.readLine();if(first==null)return;String[] request=first.split(" ");String path=request[1].split("\\?",2)[0].substring(1),line,token="",range="";while((line=input.readLine())!=null&&!line.isEmpty()){if(line.toLowerCase(Locale.ROOT).startsWith("x-audio:"))token=line.substring(8).trim();if(line.toLowerCase(Locale.ROOT).startsWith("range:"))range=line.substring(6).trim();}if(auth?!token.equals("native"):!token.isEmpty())badHeader=true;
            byte[] data;if(path.equals("live.m3u8"))data=new String(asset("sample.m3u8"),"UTF-8").replace("#EXT-X-ENDLIST","").getBytes("UTF-8");else if(path.equals("drm.m3u8"))data=("#EXTM3U\n#EXT-X-KEY:METHOD=SAMPLE-AES,URI=\"key.bin\",KEYFORMAT=\"com.apple.streamingkeydelivery\"\n#EXTINF:8,\nsegment-000.ts\n#EXT-X-ENDLIST\n").getBytes("UTF-8");else if(path.equals("cross.m3u8"))data=new String(asset("sample.m3u8"),"UTF-8").replace("segment-",cross+"/segment-").getBytes("UTF-8");else if(path.equals("slow.m3u8"))data="#EXTM3U\n#EXT-X-TARGETDURATION:10\n#EXTINF:8,\nwait.ts\n#EXT-X-ENDLIST\n".getBytes("UTF-8");else{if(path.equals("wait.ts")){held.countDown();release.await(12,TimeUnit.SECONDS);path="segment-000.ts";}data=asset(path);}
            if(path.endsWith(".ts"))segments++;if(path.equals("key.bin"))keys++;int start=0,end=data.length-1,status=200;if(range.matches("bytes=[0-9]+-[0-9]*")){String[] parts=range.substring(6).split("-",-1);start=Integer.parseInt(parts[0]);if(!parts[1].isEmpty())end=Math.min(end,Integer.parseInt(parts[1]));status=206;}if(start>=data.length||end<start)return;String type=path.endsWith(".m3u8")?"application/vnd.apple.mpegurl":path.endsWith(".m4a")?"audio/mp4":"application/octet-stream";OutputStream out=current.getOutputStream();out.write(("HTTP/1.1 "+status+" OK\r\nContent-Type: "+type+"\r\nContent-Length: "+(end-start+1)+"\r\nAccept-Ranges: bytes\r\n"+(status==206?"Content-Range: bytes "+start+"-"+end+"/"+data.length+"\r\n":"")+"Connection: close\r\n\r\n").getBytes("US-ASCII"));if(!request[0].equals("HEAD"))out.write(data,start,end-start+1);out.flush();
        }catch(Exception ignored){}}
        public void close(){closed=true;release.countDown();try{socket.close();}catch(Exception ignored){}workers.shutdownNow();}
    }
    File cache(AudioCache cache,String id,String url,boolean expected)throws Exception{CountDownLatch done=new CountDownLatch(1);boolean[] ok={false};String[] message={""};HashMap<String,String> headers=new HashMap<>();headers.put("X-Audio","native");cache.storeHls(id,id,"high",url,headers,new JSONObject().put("gain",-8).put("peak",1),(success,text)->{ok[0]=success;message[0]=text;done.countDown();});check(done.await(35,TimeUnit.SECONDS),"HLS cache timed out: "+id);check(ok[0]==expected,"HLS cache result: "+id+" "+message[0]);File file=cache.find(id,"high");check((file!=null)==expected,"partial HLS was published or complete HLS missing");return file;}
    void play(PlaybackService service,File file)throws Exception{JSONArray queue=new JSONArray().put(new JSONObject().put("uri",Uri.fromFile(file).toString()).put("title","offline-native"));test.runOnMainSync(()->{try{PlaybackService.startQueue(context,queue,0,0,80,false,false,"high");}catch(Exception e){throw new RuntimeException(e);}});helpers.await(()->service.snapshot().playing&&service.snapshot().position>180,"complete offline converted file did not play: "+service.snapshot().error);test.runOnMainSync(service::pause);int[] position={0};test.runOnMainSync(()->position[0]=service.snapshot().position);SystemClock.sleep(180);test.runOnMainSync(()->check(Math.abs(service.snapshot().position-position[0])<90,"converted audio clock advanced while paused"));test.runOnMainSync(()->{service.seek(3000);service.resume();});helpers.await(()->service.snapshot().playing&&service.snapshot().position>=3000,"converted file seek/resume failed");test.runOnMainSync(service::stopPlayback);}
    void run()throws Exception{
        String id="completion-nativeaudio";helpers.cleanup(id);SharedPreferences prefs=context.getSharedPreferences("library",0);boolean old=prefs.getBoolean("auto_cache",true);prefs.edit().putBoolean("auto_cache",true).commit();MainActivity activity=(MainActivity)test.startActivitySync(new Intent(context,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));PlaybackService[] service={null};helpers.await(()->{service[0]=(PlaybackService)FullPortChecks.field(activity,"playbackService");return service[0]!=null;},"native decoder service missing");AudioCache cache=AudioCache.shared(context);cache.clear();PluginManager manager=new PluginManager(activity);
        try(Server server=new Server(true)){
            for(int bits:new int[]{16,24}){File input=new File(context.getCacheDir(),"alac-"+bits+".m4a"),output=new File(context.getCacheDir(),"alac-"+bits+".flac");try{try(FileOutputStream out=new FileOutputStream(input)){out.write(asset("alac-"+bits+".m4a"));}NativeAudio.convert(context,input.toString(),output,AudioCache.MAX_TRACK,()->{});byte[] header=new byte[42];try(FileInputStream in=new FileInputStream(output)){check(in.read(header)==42,"FLAC stream info missing");}check(new String(header,0,4,"US-ASCII").equals("fLaC"),"ALAC decoder did not generate FLAC");long packed=0;for(int at=18;at<26;at++)packed=(packed<<8)|(header[at]&255);check(((packed>>>36)&7)==0&&((packed>>>32)&31)+1==bits,"lossless bit depth/channel count changed");play(service[0],output);}finally{input.delete();output.delete();}}
            helpers.install(manager,id,"stream",new JSONArray(),"export function stream(){return {url:'"+server.base()+"/alac-24.m4a',type:'alac',gain:-8,peak:1,headers:{'X-Audio':'native'}};}export function played(){host.storage.set('played',true);}");String track="plugin://"+id+"?id=alac";JSONArray queue=new JSONArray().put(new JSONObject().put("uri",track).put("title","ALAC source"));test.runOnMainSync(()->{try{PlaybackService.startQueue(context,queue,0,0,80,false,false,"high");}catch(Exception e){throw new RuntimeException(e);}});helpers.await(()->service[0].snapshot().playing&&service[0].snapshot().position>150,"ALAC source did not decode and play: "+service[0].snapshot().error);check(cache.find(track,"high")!=null&&cache.metadata(track,"high").optDouble("gain")==-8,"decoded source did not retain offline gain metadata");helpers.await(()->context.getSharedPreferences("plugin_data_"+id,0).getString("played","").equals("true"),"decoded source did not report played");test.runOnMainSync(service[0]::stopPlayback);
            File master=cache(cache,"native-master",server.base()+"/master.m3u8",true),encrypted=cache(cache,"native-encrypted",server.base()+"/encrypted.m3u8",true);check(server.segments>=8&&server.keys>0,"complete manifests, segments or AES key were not fetched");check(!server.badHeader,"manifest/segment/key lost source request headers");
            cache(cache,"native-live",server.base()+"/live.m3u8",false);cache(cache,"native-drm",server.base()+"/drm.m3u8",false);
            try(Server child=new Server(false)){server.cross=child.base();cache(cache,"native-cross",server.base()+"/cross.m3u8",true);check(child.segments>0&&!child.badHeader,"HLS segment received another origin's authorization header");}
            CountDownLatch cancelled=new CountDownLatch(1);boolean[] result={true};Map<String,String> headers=new HashMap<>();headers.put("X-Audio","native");cache.storeHls("native-cancel","cancel","high",server.base()+"/slow.m3u8",headers,new JSONObject(),(ok,message)->{result[0]=ok;cancelled.countDown();});check(server.held.await(12,TimeUnit.SECONDS),"cache cancellation did not reach segment");cache.clear();server.release.countDown();check(cancelled.await(15,TimeUnit.SECONDS)&&!result[0]&&cache.find("native-cancel","high")==null,"clearing cache published an in-flight partial song");
            // Recreate final files after clear, then remove the server and source before playing.
            master=cache(cache,"native-master",server.base()+"/master.m3u8",true);encrypted=cache(cache,"native-encrypted",server.base()+"/encrypted.m3u8",true);server.close();prefs.edit().putBoolean("plugin_enabled_"+id,false).commit();play(service[0],master);play(service[0],encrypted);check(!cache.busy(),"native offline jobs leaked");
            System.out.println("MYGO_NATIVE_AUDIO_OK: real Android 16/24-bit ALAC to lossless FLAC; source playback and metadata; master/AES HLS offline audio with server stopped; per-origin headers; live/DRM rejection; cache cancellation; native pause/seek/resume clock");
        }finally{test.runOnMainSync(()->{service[0].stopPlayback();manager.close();activity.finish();});cache.clear();prefs.edit().putBoolean("auto_cache",old).remove("plugin_enabled_"+id).commit();helpers.cleanup(id);}
    }
}
